    internal static int EtEnd(byte[] b) {
        // A golden's end: its length less one final newline (see jsontest).
        int n = emon.Port.BlobLen(b);
        if ((n > 0) && (emon.Port.BlobU8(b, n - 1) == 10)) {
            return n - 1;
        }
        return n;
    }
